package fraymus.workspace;

import org.json.*;
import java.util.*;

/** A second registered content contract. Existing101 code and evidence remain unchanged. */
final class DataSummary102 {
    static final String KIND="motion-summary-workflow-102-v1";
    static boolean supported(String kind){return DataCreation101.KIND.equals(kind)||KIND.equals(kind);}
    static boolean requested(String text){return !ChatPolicy044.has(text,"\\b(native|physics|simulate|simulation|predict)\\b")&&ChatPolicy044.has(text,"\\banaly[sz]e\\b")&&ChatPolicy044.has(text,"\\b(data|dataset|csv)\\b")&&ChatPolicy044.has(text,"\\b(create|build)\\b.*\\b(motion summary|summary report|motion report)\\b");}
    static JSONObject definition(JSONObject in,MeasurementStore store){if(DataCreation101.KIND.equals(in.optString("profile101")))return DataCreation101.definition(in,store);if(!KIND.equals(in.optString("profile101")))throw new IllegalArgumentException("Unknown registered content procedure");return DataCreation101.definition(WorldFrames.copy(in).put("profile101",DataCreation101.KIND),store).put("profile101",KIND);}
    static String code(String kind){if(DataCreation101.KIND.equals(kind))return DataCreation101.code();try{var digest=java.security.MessageDigest.getInstance("SHA-256");for(Class<?> type:List.of(DataSummary102.class,DataCreation101.class,MotionData.class))try(var in=type.getResourceAsStream(type.getSimpleName()+".class")){digest.update(in.readAllBytes());}return java.util.HexFormat.of().formatHex(digest.digest());}catch(Exception e){throw new IllegalStateException(e);}}
    static JSONObject summary(JSONObject handoff){var q=handoff.getJSONObject("quality");var out=new JSONObject();out.put("samples",String.valueOf(q.getInt("rowCount"))).put("duration",n(q.getDouble("durationS"))).put("travel",n(q.getDouble("totalTravelM"))).put("peak",n(q.getDouble("peakAbsVelocityMps"))).put("gaps",String.valueOf(q.getInt("gapFlags"))).put("speeds",String.valueOf(q.getInt("speedFlags")));return out;}
    private static String n(double x){return String.format(Locale.ROOT,"%.6f",x);}
    static JSONObject creation(JSONObject w,JSONObject handoff){var out=DataCreation101.creation(w,handoff);if(!KIND.equals(w.optString("profile101")))return out;var metrics=summary(handoff);var checks=out.getJSONArray("checks");for(String k:List.of("samples","duration","travel","peak","gaps","speeds"))checks.put(new JSONObject().put("selector","#summary-"+k).put("expectText",metrics.getString(k)));checks.put(new JSONObject().put("selector","#motion-trace").put("expectCount",1));
        String extra=" This is a motion SUMMARY REPORT. Preserve every table, filter and quality requirement above. Above the scrollable table, show visible summary cards with the following exact numeric text and IDs (no units inside these values): "+metrics+". IDs are #summary-samples, #summary-duration, #summary-travel, #summary-peak, #summary-gaps, #summary-speeds. Put units in separate labels: samples, duration seconds, travel metres, peak speed m/s, gap flags, speed flags. Values are derived from the complete source; filtering changes the table only, never the summary or chart. Add one visible native SVG id=motion-plot, viewBox='0 0 640 240', width=100%, with one direct-child polyline id=motion-trace, fill=none, visible stroke width2. No transform attribute or CSS transform on the SVG or polyline. Use all original source.rows in order: t=Number(row.time_s), d=Number(row.displacement_m). t0=first t; tn=last t; lo=Math.min(0,...all d); hi=Math.max(0,...all d). Each actual SVG point must be x=40+560*(t-t0)/(tn-t0), y=200-160*(d-lo)/Math.max(1e-12,hi-lo). Do not smooth, subsample or invent points. Flat traces must remain visible. Show exact visible labels #time-axis='Time (s)' and #distance-axis='Displacement (m)'. SVG trace and all summary values remain unchanged in all four filter states. Keep the whole report compact and readable; scroll long tables. Use original source-derived values, not a screenshot or hardcoded trace.";
        return out.put("request",out.getString("request").replace("no libraries or charts","no libraries")+extra);
    }
    static JSONObject audit(JSONObject w,JSONObject artifact,JSONObject data,JSONObject handoff,JSONObject actual)throws Exception{
        if(!KIND.equals(w.optString("profile101")))return DataCreation101.audit(artifact,data,handoff,actual);
        SpatialScene.keys(actual,"id","version","frames","summaries102");var base=WorldFrames.copy(actual);base.remove("summaries102");var result=DataCreation101.audit(artifact,data,handoff,base);var errors=result.getJSONArray("errors");var observations=actual.getJSONArray("summaries102");if(observations.length()!=4)throw new IllegalArgumentException("Require summary and trace observations in all four states");
        var expected=summary(handoff);var rows=MotionData.originalRows(data);double t0=rows.getJSONObject(0).getDouble("timeS"),tn=rows.getJSONObject(rows.length()-1).getDouble("timeS"),lo=0,hi=0;for(Object raw:rows){double d=((JSONObject)raw).getDouble("distanceM");lo=Math.min(lo,d);hi=Math.max(hi,d);}double range=Math.max(1e-12,hi-lo),maxError=0;
        for(int f=0;f<4;f++){var o=observations.getJSONObject(f);SpatialScene.keys(o,"values","points","viewBox","visible","timeAxis","distanceAxis");if(!o.getJSONObject("values").similar(expected))errors.put("Summary"+f+": original full-source values differ");if(!o.getBoolean("visible"))errors.put("Summary"+f+": values or trace hidden");if(!o.getString("timeAxis").equals("Time (s)")||!o.getString("distanceAxis").equals("Displacement (m)"))errors.put("Summary"+f+": axis units changed");if(!o.getJSONArray("viewBox").similar(new JSONArray(List.of(0,0,640,240))))errors.put("Summary"+f+": chart coordinates changed");var points=o.getJSONArray("points");if(points.length()!=rows.length())errors.put("Summary"+f+": trace omitted or invented samples");for(int i=0;i<Math.min(points.length(),rows.length());i++){var p=points.getJSONArray(i);if(p.length()!=2)throw new IllegalArgumentException("Require actual XY points");var row=rows.getJSONObject(i);double x=40+560*(row.getDouble("timeS")-t0)/(tn-t0),y=200-160*(row.getDouble("distanceM")-lo)/range;double dx=p.getDouble(0)-x,dy=p.getDouble(1)-y;if(!Double.isFinite(dx)||!Double.isFinite(dy))throw new IllegalArgumentException("Non-finite trace");maxError=Math.max(maxError,Math.max(Math.abs(dx),Math.abs(dy)));} }
        if(maxError>.002)errors.put("Actual SVG trace differs from original mapped source by "+maxError+" units");return result.put("passed",errors.isEmpty()).put("summaries102",observations).put("maxTraceError102",maxError);
    }
    static JSONObject procedure(JSONObject w){var p=DataCreation101.procedure(w);if(!KIND.equals(w.optString("profile101")))return p;return p.put("kind",KIND).put("scope",DataCreation101.SCOPE+" Motion summary and displacement trace plus exact source explorer; no arbitrary pipeline or model-weight training.").put("actions",new JSONArray(List.of("Verify original data","Bind normalized source","Generate actual summary report","Check every source cell, summary and SVG point in all filter states","Publish after durable verified parent completion")));}
}
